/**
 * New Client Intake -> SignWell action dispatcher.
 * Creates a draft for new intake records and sends an existing draft only
 * when Send SignWell Agreement is explicitly checked.
 */
const TABLE_NAME = "New Client Intake";
const DISPATCHER_URL =
  "https://n8n.dulcy.io/webhook/REDACTED_PATH";

const { recordId } = input.config();

if (!recordId || !String(recordId).startsWith("rec")) {
  throw new Error("A valid Airtable record ID is required.");
}

const table = base.getTable(TABLE_NAME);
const record = await table.selectRecordAsync(recordId);

if (!record) {
  throw new Error("The Airtable record could not be found.");
}

const documentId = record
  .getCellValueAsString("SignWell Document ID")
  .trim();
const agreementStatus = record
  .getCellValueAsString("Agreement Status")
  .trim();
const createRequested = Boolean(
  record.getCellValue("Create SignWell Draft")
);
const sendRequested = Boolean(
  record.getCellValue("Send SignWell Agreement")
);

let action;

if (sendRequested) {
  if (!documentId) {
    throw new Error(
      "A SignWell draft must exist before Send SignWell Agreement can run."
    );
  }
  action = "Send SignWell Agreement";
} else if (!documentId && (createRequested || !agreementStatus)) {
  action = "Create SignWell Draft";
} else {
  if (createRequested && documentId) {
    await table.updateRecordAsync(recordId, {
      "Create SignWell Draft": false,
    });
  }
  output.set("skipped", true);
  output.set("reason", "No valid SignWell action is currently requested.");
  return;
}

if (action === "Create SignWell Draft") {
  await table.updateRecordAsync(recordId, {
    "Create SignWell Draft": true,
    "Send SignWell Agreement": false,
    "Agreement Status": { name: "Pending Creation" },
    "SignWell Error": "",
  });
} else {
  await table.updateRecordAsync(recordId, {
    "SignWell Error": "",
  });
}

try {
  const response = await fetch(DISPATCHER_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ recordId, action }),
  });

  if (!response.ok) {
    const detail = await response.text();
    throw new Error(
      "SignWell dispatcher returned HTTP " +
        response.status +
        ": " +
        (detail || "No response body")
    );
  }

  output.set("dispatched", true);
  output.set("recordId", recordId);
  output.set("action", action);
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);

  await table.updateRecordAsync(recordId, {
    "Agreement Status": { name: "Error" },
    "SignWell Error": message.slice(0, 9000),
  });

  throw error;
}
